-- ADR-0055 decision 7 (contract `TargetStatus.name_case`): the canonical name case semantics of the
-- latest heartbeat per target, with the time of its last change and the debounced inventory state
-- (due since, last run). Generated by drizzle-kit. Nullable columns without a default: catalog-only
-- changes. The CHECK is validated in this migration on purpose: `agent_targets` holds one row per
-- declared target (at most 64 per agent), never a large table, and every existing row has a null
-- `name_case` (the bounded-notes CHECK of 0028 was added the same way). The runtime role already
-- has table-level UPDATE on `agent_targets` (migration 0003).
ALTER TABLE "agent_targets" ADD COLUMN "name_case" jsonb;--> statement-breakpoint
ALTER TABLE "agent_targets" ADD COLUMN "name_case_changed_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "agent_targets" ADD COLUMN "name_case_inventory_due_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "agent_targets" ADD COLUMN "name_case_inventory_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "agent_targets" ADD CONSTRAINT "agent_targets_name_case_bounded" CHECK ("agent_targets"."name_case" is null or (jsonb_typeof("agent_targets"."name_case") = 'object' and octet_length("agent_targets"."name_case"::text) <= 16384));